// js/word-weaver-points.js - Word Weaver's stars, pure (no DOM, no storage). Used by the game
// (word-weaver/js/ui.js), the stats store (js/game-stats.js), the cross-device merge
// (js/players-agg.js), My Stats and the leaderboard, so all of them agree on every number.
//
// THE LADDER: levels 1, 2, 3... (word-weaver/data/, GENERATED by tools/build-word-weaver-data.mjs),
// played in order, one ladder, no difficulty. No replays: a level is scored ONCE, at its first
// completion. Hints are unlimited; a hint reveals one letter.
//
// STARS (Matt, 2026-10-28): a level finished with no hint = 3 stars, 1 hint = 2, 2 or more = 1.
//
// WHAT IS STORED (the `ww` sub-counter, js/game-stats.js `recordWordWeaver`):
//   ww.lv['L<n>'] = { s, h, t }   level n: s = stars 1-3, h = hints used, t = when it was first
//                                 completed (ms).
//   ww.x = n                      lifetime extra words found (a counter; it only goes up).
// Keys are 'L13', never a bare number: Firebase turns an object with mostly numeric keys into an
// ARRAY. Each field only improves (THE LAW rule 2: stars Math.max, hints Math.min, the earliest
// time), and the cross-device merge takes the best of each, so a level finished on two phones
// counts ONCE.
//
// TOTAL STARS are the leaderboard's number: the sum over every DISTINCT level completed.

/** Stars for a level finished with `hints` hints: 0 -> 3, 1 -> 2, 2+ -> 1. */
export function wwStarsFor(hints) {
  const h = Math.max(0, Math.floor(Number(hints) || 0));
  return h === 0 ? 3 : h === 1 ? 2 : 1;
}

/** One stored level entry, cleaned, or null. A missing star count is read from the hints (rule 4:
 *  nothing is invented beyond what the hints already say); a missing hint count stays unknown (-1
 *  is never stored; the entry just has no h). */
function entry(e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return null;
  const hasH = Number.isFinite(Number(e.h)) && e.h !== null && e.h !== '';
  const h = hasH ? Math.max(0, Math.floor(Number(e.h))) : null;
  let s = Math.floor(Number(e.s) || 0);
  if (!(s >= 1)) s = h == null ? 1 : wwStarsFor(h);
  const out = { s: Math.min(3, s) };
  if (h != null) out.h = h;
  const t = Math.floor(Number(e.t) || 0);
  if (t > 0) out.t = t;
  return out;
}

/** The better of two entries for one level, field by field (the cross-device merge, and the
 *  recorder's "only if better"). */
export function wwBest(a, b) {
  const x = entry(a), y = entry(b);
  if (!x) return y;
  if (!y) return x;
  const out = { s: Math.max(x.s, y.s) };
  if (x.h != null || y.h != null) out.h = Math.min(x.h ?? Infinity, y.h ?? Infinity);
  if (x.t || y.t) out.t = Math.min(x.t || Infinity, y.t || Infinity);
  return out;
}

/** A record's completed levels as { n: { s, h?, t? } }, n a number >= 1. `rec` is `games.wordweaver`. */
export function wwLevels(rec) {
  const lv = (rec && rec.ww && rec.ww.lv) || {};
  const out = {};
  if (!lv || typeof lv !== 'object') return out;
  for (const k of Object.keys(lv)) {
    const m = /^L(\d+)$/.exec(k);
    if (!m || +m[1] < 1) continue;
    const e = entry(lv[k]);
    if (e) out[+m[1]] = out[+m[1]] ? wwBest(out[+m[1]], e) : e;
  }
  return out;
}

/** Total stars over distinct levels: the leaderboard's number. */
export function wwStars(rec) {
  const lv = wwLevels(rec);
  let s = 0;
  for (const k of Object.keys(lv)) s += lv[k].s;
  return s;
}
/** Levels completed. */
export function wwCleared(rec) { return Object.keys(wwLevels(rec)).length; }
/** Levels completed with three stars (no hint). */
export function wwThreeStars(rec) {
  const lv = wwLevels(rec);
  return Object.keys(lv).filter((k) => lv[k].s === 3).length;
}
/** Lifetime extra words found. */
export function wwExtra(rec) {
  const x = Math.floor(Number(rec && rec.ww && rec.ww.x) || 0);
  return x > 0 ? x : 0;
}
